<?php require __DIR__.'/includes/bootstrap.php';$c=$_GET['code']??'';$q=$db->prepare('SELECT * FROM links WHERE short_code=? AND status="active" LIMIT 1');$q->execute([$c]);$l=$q->fetch();if(!$l){http_response_code(404);exit('Link not found');}$ua=$_SERVER['HTTP_USER_AGENT']??'';$bot=(bool)preg_match('/bot|crawler|spider|preview|facebookexternalhit|slackbot|discordbot/i',$ua);$db->prepare('INSERT INTO click_events(link_id,is_bot,user_agent,ip_hash,referer,created_at) VALUES(?,?,?,?,?,NOW())')->execute([$l['id'],$bot?1:0,substr($ua,0,1000),hash('sha256',($_SERVER['REMOTE_ADDR']??'').'|'.$config['app']['name']),substr($_SERVER['HTTP_REFERER']??'',0,2048)]);$db->prepare('UPDATE links SET '.($bot?'bot_click_count=bot_click_count+1':'click_count=click_count+1').' WHERE id=?')->execute([$l['id']]);header('Location:'.$l['destination_url'],true,302);exit;